#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;

const int N = 250005;
const int M = 1 << 17;
const int D = 18;

int P;
int L, K, fac[N], ifac[N], bitcnt[N], bit[20], n, m;
ll sumA[D * M], sumC[D * M];
ull dp[D * M], tmp[D * M];

int power(int a, int t) {
    int r = 1;
    while (t) {
        if (t & 1) r = (ll)r * a % P;
        a = (ll)a * a % P;
        t >>= 1;
    }
    return r;
}

int main() {
    scanf("%d%d%d", &L, &K, &P);

    fac[0] = 1;
    for (int i = 1; i <= L; ++i) {
        fac[i] = (ll)fac[i - 1] * i % P;
        bitcnt[i] = bitcnt[i >> 1] + (i & 1);
    }

    ll all = power(K, L);
    if (L & 1) {
        printf("%lld\n", all);
        return 0;
    }

    ifac[L] = power(fac[L], P - 2);
    for (int i = L; i >= 1; --i) ifac[i - 1] = (ll)ifac[i] * i % P;

    for (int i = 1; (1 << i) <= L; ++i)
        if ((L >> i) & 1) bit[n++] = 1 << i;
    m = 1 << n;

    for (int mask = 0; mask < m; ++mask) {
        int s = 0;
        for (int j = 0; j < n; ++j)
            if ((mask >> j) & 1) s += bit[j];
        sumA[bitcnt[mask] * M + mask] = ifac[s];
    }

    for (int t = 0; t <= n; ++t) {
        ll *a = sumA + t * M;
        for (int len = m; len >= 2; len >>= 1) {
            int half = len >> 1;
            for (int j = 0; j < m; j += len)
                for (int k = 0; k < half; ++k)
                    a[j + k + half] += a[j + k];
        }
        for (int j = 0; j < m; ++j) a[j] %= P;
    }

    for (int t = 0; t <= n; ++t)
        memcpy(dp + t * M, sumA + t * M, m * sizeof(ull));

    int cc = 0, revK = 0;
    while (K) {
        revK = (revK << 1) | (K & 1);
        ++cc;
        K >>= 1;
    }

    for (--cc, revK >>= 1; cc; --cc, revK >>= 1) {
        for (int t = 0; t <= n; ++t)
            memset(tmp + t * M, 0, m * sizeof(ull));

        for (int a = 0; a <= n; ++a)
            for (int b = 0; a + b <= n; ++b) {
                ull *f = tmp + (a + b) * M;
                ull *g = dp + a * M;
                ull *h = dp + b * M;
                for (int j = 0; j < m; ++j) f[j] += g[j] * h[j];
            }

        for (int t = 0; t <= n; ++t)
            for (int j = 0; j < m; ++j)
                dp[t * M + j] = tmp[t * M + j] % P;

        if (revK & 1) {
            for (int t = 0; t <= n; ++t)
                memset(tmp + t * M, 0, m * sizeof(ull));

            for (int a = 0; a <= n; ++a)
                for (int b = 0; a + b <= n; ++b) {
                    ull *f = tmp + (a + b) * M;
                    ull *g = dp + a * M;
                    ll *h = sumA + b * M;
                    for (int j = 0; j < m; ++j) f[j] += g[j] * h[j];
                }

            for (int t = 0; t <= n; ++t)
                for (int j = 0; j < m; ++j)
                    dp[t * M + j] = tmp[t * M + j] % P;
        }
    }

    for (int t = 0; t <= n; ++t)
        memcpy(sumC + t * M, dp + t * M, m * sizeof(ull));

    for (int t = 0; t <= n; ++t) {
        ll *a = sumC + t * M;
        for (int len = 2; len <= m; len <<= 1) {
            int half = len >> 1;
            for (int j = 0; j < m; j += len)
                for (int k = 0; k < half; ++k)
                    a[j + k + half] -= a[j + k];
        }
        for (int j = 0; j < m; ++j) a[j] = (a[j] % P + P) % P;
    }

    ll ans = (all - sumC[n * M + ((1 << n) - 1)] * fac[L] % P + P) % P;
    printf("%lld\n", ans);
    return 0;
}
